import { useEffect, useMemo, useState } from "react";
import { getSessionUser, ISOString, isValidDate, NumberFormat } from '../../../Components/functions'
import { fetchLink } from "../../../Components/fetchComponent";
import { IconButton, Tooltip } from "@mui/material";
import { ArrowRight, Search } from "@mui/icons-material";
import { useNavigate } from "react-router-dom";
import AppTableComponent from "../../../Components/appTable/appTableComponent";

const defaultFilters = {
    Fromdate: ISOString(),
    Todate: ISOString(),
};

const getDayBookCookie = () => {
    const match = document.cookie.match(new RegExp('(^| )dayBookFilters=([^;]+)'));
    if (match) {
        try { return JSON.parse(match[2]); } catch (e) { }
    }
    return null;
}

const setDayBookCookie = (filters) => {
    document.cookie = `dayBookFilters=${JSON.stringify(filters)}; path=/; max-age=86400`;
}

const DayBookOfERP = ({ loadingOn, loadingOff }) => {
    const navigate = useNavigate();
    const user = getSessionUser().user;
    const [dayBookData, setDayBookData] = useState([]);
    
    const cookieFilters = getDayBookCookie();
    
    const [filters, setFilters] = useState({
        Fromdate: cookieFilters?.Fromdate && isValidDate(cookieFilters?.Fromdate) ? cookieFilters.Fromdate : defaultFilters.Fromdate,
        Todate: cookieFilters?.Todate && isValidDate(cookieFilters?.Todate) ? cookieFilters.Todate : defaultFilters.Todate,
        fetchFrom: cookieFilters?.Fromdate && isValidDate(cookieFilters?.Fromdate) ? cookieFilters.Fromdate : defaultFilters.Fromdate,
        fetchTo: cookieFilters?.Todate && isValidDate(cookieFilters?.Todate) ? cookieFilters.Todate : defaultFilters.Todate,
    })

    useEffect(() => {
        if (loadingOn) loadingOn();
        setDayBookData([])
        fetchLink({
            address: `dashboard/dayBook?Fromdate=${filters?.fetchFrom}&Todate=${filters?.fetchTo}`,
            headers: {
                "Db": user?.Company_id
            }
        }).then(data => {
            if (data.success) {
                setDayBookData(data.data);
            }
        }).finally(() => {
            if (loadingOff) loadingOff();
        }).catch(e => console.error(e))
    }, [filters?.fetchFrom, filters?.fetchTo])

    const handleSearch = () => {
        const newFilters = { Fromdate: filters.Fromdate, Todate: filters.Todate };
        setDayBookCookie(newFilters);
        setFilters(pre => ({ ...pre, fetchFrom: filters.Fromdate, fetchTo: filters.Todate }));
    };

    const flatData = useMemo(() => {
        return dayBookData.flatMap(group => group.groupedData || []);
    }, [dayBookData]);

    const columns = [
        { Field_Name: 'ModuleName', ColumnHeader: 'Module', isVisible: 1 },
        { Field_Name: 'Voucher_Type', ColumnHeader: 'Voucher', isVisible: 1 },
        { Field_Name: 'VoucherBreakUpCount', ColumnHeader: 'Entries', Fied_Data: 'number', isVisible: 1, Aggregation: 'sum' },
        { Field_Name: 'Amount', ColumnHeader: 'Amount', Fied_Data: 'number', isVisible: 1, Aggregation: 'sum' },
        {
            Field_Name: 'Action',
            ColumnHeader: 'Details',
            isVisible: 1,
            isCustomCell: true,
            Cell: ({ row }) => (
                <div className="text-center">
                    <Tooltip title={'Open ' + row?.Voucher_Type + ' Details'}>
                        <button
                            onClick={() => {
                                navigate(row?.navLink, {
                                    state: {
                                        Fromdate: filters?.fetchFrom,
                                        Todate: filters?.fetchTo,
                                        VoucherType: {
                                            value: row?.Voucher_Type_Id,
                                            label: row?.Voucher_Type || `Voucher ${row?.Voucher_Type_Id}`
                                        },
                                        navigationDetails: { path: '/erp/dayBook' }
                                    }
                                });
                            }}
                            className="icon-btn"
                        >
                            <ArrowRight sx={{ fontSize: 'inherit' }} />
                        </button>
                    </Tooltip>
                </div>
            )
        }
    ];

    return (
        <AppTableComponent
            title="Day Book"
            dataArray={flatData}
            columns={columns}
            EnableSerialNumber={true}
            defaultGrouping={['ModuleName']}
            ButtonArea={
                <div className="d-flex align-items-center gap-2 me-3">
                    <input
                        type="date"
                        value={filters.Fromdate}
                        onChange={e => setFilters({ ...filters, Fromdate: e.target.value })}
                        className="cus-inpt w-auto p-1"
                    />
                    <span className="px-2">To</span>
                    <input
                        type="date"
                        value={filters.Todate}
                        onChange={e => setFilters({ ...filters, Todate: e.target.value })}
                        className="cus-inpt w-auto p-1"
                    />
                    <IconButton onClick={handleSearch} variant="outlined" size="small">
                        <Search />
                    </IconButton>
                </div>
            }
        />
    )
}

export default DayBookOfERP;